    public sealed partial class ZTrackerModelWindow
    {
        /// <summary>Disposable authoring fixtures exercise actual controls, identity remapping, references and Undo. No Test Runner or user assets.</summary>
        public static string CheckMixerWorkflow()
        {
            var report=new StringBuilder();int passed=0,failed=0;
            var window=CreateInstance<ZTrackerModelWindow>();var asset=CreateInstance<ZTrackerSong>();asset.schemaVersion=1;var inst=CreateInstance<ZTrackerInstrument>();ZTrackerMigration.Upgrade(inst,out _);
            asset.model=TrackerEngineCheck.FixtureSong(inst);window.song=asset;window.pane=1;window.Show();window.CreateGUI();
            void Need(bool condition,string message){if(!condition)throw new Exception(message);}
            void Check(string label,Action run){try{run();passed++;report.AppendLine("PASS "+label);}catch(Exception e){failed++;report.AppendLine("FAIL "+label+": "+e.Message);}}
            void Click(string name){LayoutChain(window);var button=window.rootVisualElement.Q<Button>(name);Need(button!=null,"Missing action "+name);var invoke=typeof(Clickable).GetMethod("SimulateSingleClick",BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public);Need(invoke!=null,"Clickable simulator unavailable");invoke.Invoke(button.clickable,new object[]{null,0});}
            void DoubleClick(VisualElement target){Need(target!=null,"Reset control missing");LayoutChain(window);var root=target.panel.visualTree;var at=target.worldBound.center;using(var down=PointerDownEvent.GetPooled(new Event{type=EventType.MouseDown,button=0,clickCount=2,mousePosition=at})){down.target=target;target.SendEvent(down);}PointerRelease(root,at);}
            void PickEffect(string label)
            {
                var panel=window.rootVisualElement.panel;
                panel.GetType().GetMethod("ValidateLayout",BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic)?.Invoke(panel,null);
                var item=window.rootVisualElement.Query<VisualElement>(className:"zui-menu__item").ToList().FirstOrDefault(e=>e.Query<Label>().ToList().Any(l=>l.text==label));
                Need(item!=null,"Missing effect picker item "+label);
                using(var down=PointerDownEvent.GetPooled(new Event{type=EventType.MouseDown,button=0,mousePosition=item.worldBound.center})){down.target=item;item.SendEvent(down);}
                using(var up=PointerUpEvent.GetPooled(new Event{type=EventType.MouseUp,button=0,mousePosition=item.worldBound.center})){up.target=item;item.SendEvent(up);}
            }
            try
            {
                Check("type popover exposes roles; additions preserve pattern records and Undo",()=>{Click("add-track");Need(window.rootVisualElement.Query<VisualElement>(className:"zui-menu__item").ToList().Any(),"Track type popover did not open");window.AddTrack(TrackKind.Group);window.AddTrack(TrackKind.Send);window.AddTrack(TrackKind.Event);Need(asset.model.tracks.Select(t=>t.kind).Distinct().Count()==5,"Missing a track role");Need(asset.model.patterns.All(p=>p.tracks.Count==asset.model.tracks.Count),"Pattern records not updated");int count=asset.model.tracks.Count;Undo.PerformUndo();Need(asset.model.tracks.Count==count-1&&asset.model.patterns[0].tracks.Count==count-1,"Undo did not restore track topology");Undo.PerformRedo();Need(asset.model.tracks.Count==count,"Redo did not restore track topology");window.AddTrack(TrackKind.Master);Need(asset.model.tracks.Count==count,"Duplicate Master accepted");});
                Check("track reorder preserves identity-based routing, automation, selection and Undo",()=>{window.track=0;var selected=window.SelectedTrack;string selectedId=selected.id;var before=asset.model.tracks.Select(t=>t.id).ToArray();var pattern=window.Pattern;var record=pattern.tracks.Find(t=>t.trackId==selectedId);record.automation.Add(new AutomationLane{id="move-lane",target=new ParameterTarget{kind=ParameterKind.Mixer,trackId=selectedId,parameter="postVolume"}});var bus=asset.model.tracks.Find(t=>t.kind==TrackKind.Send);selected.sends.Add(new SendDestination{trackId=bus.id});window.ReorderTracks(0,2);Need(window.SelectedTrack.id==selectedId&&asset.model.tracks[2].id==selectedId,"Selection did not follow moved track");Need(pattern.tracks.Find(t=>t.trackId==selectedId)==record&&record.automation.Last().target.trackId==selectedId,"Pattern or automation followed index instead of identity");Need(selected.sends[0].trackId==bus.id,"Routing changed on reorder");Undo.PerformUndo();Need(asset.model.tracks.Select(t=>t.id).SequenceEqual(before),"Undo did not restore order");var restored=asset.model.tracks.Find(t=>t.id==selectedId);restored.sends.RemoveAll(s=>s.trackId==bus.id);window.Pattern.tracks.Find(t=>t.trackId==selectedId).automation.RemoveAll(l=>l.id=="move-lane");window.track=asset.model.tracks.IndexOf(restored);});
                Check("mixer rows drag with live slide, drop once, keep selection and Undo",()=>{window.pane=1;window.track=0;window.BuildPane();LayoutChain(window);var before=asset.model.tracks.Select(t=>t.id).ToArray();string selectedId=before[0];
                    var row0=window.rootVisualElement.Q<Label>("track-select-0");var row1=window.rootVisualElement.Q<Label>("track-select-1");var row2=window.rootVisualElement.Q<Label>("track-select-2");Need(row0!=null&&row2!=null&&row0.worldBound.height>0,"Mixer rows not laid out");float pitch=row1.worldBound.yMin-row0.worldBound.yMin;
                    var dropAt=row2.worldBound.center+new Vector2(0,2);float travel=dropAt.y-row0.worldBound.center.y;PointerDrag(row0,dropAt,8,midDrag:()=>{Need(ZuiReorder.Busy,"Drag did not start");Need(Mathf.Abs(TranslateY(row0)-travel)<.5f,"Dragged row does not follow the pointer: "+TranslateY(row0)+" vs "+travel);Need(Mathf.Abs(TranslateY(row1)+pitch)<1f&&Mathf.Abs(TranslateY(row2)+pitch)<1f,"Rows below did not slide up to make room: "+TranslateY(row1)+"/"+TranslateY(row2)+" pitch "+pitch);Need(row1.ClassListContains("zui-reorder__shifting"),"Making-room rows are not animated");Need(asset.model.tracks.Select(t=>t.id).SequenceEqual(before),"Data changed before the drop");},finish:false);
                    Need(asset.model.tracks.Select(t=>t.id).SequenceEqual(before),"Data changed before the dropped row settled");ZuiReorder.FinishPending();
                    Need(asset.model.tracks[2].id==selectedId&&window.SelectedTrack.id==selectedId,"Drop did not move the row to the third place or lost selection");Undo.PerformUndo();Need(asset.model.tracks.Select(t=>t.id).SequenceEqual(before),"One Undo did not restore order");
                    window.BuildPane();LayoutChain(window);var click=window.rootVisualElement.Q<Label>("track-select-1");PointerClick(click);Need(window.track==1&&!ZuiReorder.Busy&&asset.model.tracks.Select(t=>t.id).SequenceEqual(before),"A click selected nothing or reordered");window.track=0;});
                Check("routing pickers exclude group ancestry and send feedback cycles",()=>{var song=asset.model;var group=song.tracks.Find(t=>t.kind==TrackKind.Group);var send=song.tracks.Find(t=>t.kind==TrackKind.Send);var seq=song.tracks.Find(t=>t.kind==TrackKind.Sequencer);seq.parentGroupId=group.id;Need(!window.RouteAllowed(group,seq.id,true),"Non-group or ancestry cycle allowed");send.outputTrackId=group.id;Need(!window.SendAllowed(group,send.id),"Send feedback cycle allowed");send.outputTrackId="";Need(window.SendAllowed(seq,send.id),"Valid send excluded");});
                Check("clone remaps device declarations and sparse automation without aliasing",()=>{window.track=0;var t=window.SelectedTrack;t.devices.nodes.Add(new AudioEffectNodeData{type=ZoundEffectType.Gain,uid="clone-gain",p=new[]{.7f}});window.DeclareNativeSource(t,t.devices.nodes[0]);var pt=window.Pattern.tracks.Find(p=>p.trackId==t.id);pt.automation.Add(new AutomationLane{id="clone-lane",target=new ParameterTarget{kind=ParameterKind.Device,trackId=t.id,deviceId="clone-gain",index=0,parameter="1",units="linear"},points=new List<AutomationPoint>{new AutomationPoint{line=.375,value=.25f}}});window.CloneTrack();var copy=window.SelectedTrack;Need(copy.id!=t.id&&copy.devices.nodes[0].uid!=t.devices.nodes[0].uid,"Clone identities aliased");Need(copy.sourceDevices[0].id==copy.devices.nodes[0].uid&&copy.sourceDevices[0].parameters[0].target.deviceId==copy.devices.nodes[0].uid,"Source identity not remapped");var lane=window.Pattern.tracks.Find(p=>p.trackId==copy.id).automation[0];Need(lane.target.trackId==copy.id&&lane.target.deviceId==copy.devices.nodes[0].uid,"Lane retargeted to original");copy.devices.nodes[0].p[0]=.4f;Need(t.devices.nodes[0].p[0]==.7f,"Clone data aliases original");Need(ZTrackerModelValidation.Validate(asset.model)==null,ZTrackerModelValidation.Validate(asset.model));});
                Check("device reorder carries send taps and stable command ordinals",()=>{var t=window.SelectedTrack;var send=asset.model.tracks.Find(x=>x.kind==TrackKind.Send);t.devices.nodes.Add(new AudioEffectNodeData{type=ZoundEffectType.Gain,uid="tap-two",p=new[]{1f}});t.sends.Add(new SendDestination{trackId=send.id,devicePosition=1});int ordinal=t.sourceDevices[0].ordinal;var before=t.devices.nodes.ToArray();Move(t.devices.nodes,0,1);window.RepairChainReferences(t,before);Need(t.sends[0].devicePosition==2,"Send silently moved to another node");Need(t.sourceDevices[0].ordinal==ordinal&&t.sourceDevices[0].parameters[0].target.deviceId==before[0].uid,"Literal command declaration retargeted");});
                Check("remove track flags cross-track lanes and restores via Undo",()=>{var target=window.SelectedTrack;var other=asset.model.tracks[0];var pt=window.Pattern.tracks.Find(p=>p.trackId==other.id);pt.automation.Add(new AutomationLane{id="cross",target=new ParameterTarget{kind=ParameterKind.Mixer,trackId=target.id,parameter="postVolume"}});asset.model.sequence[0].mutedTrackIds.Add(target.id);window.RemoveTrack();Need(!asset.model.tracks.Contains(target)&&pt.automation.Last().unsupported,"Deletion did not flag cross-track reference");Need(!asset.model.sequence[0].mutedTrackIds.Contains(target.id),"Sequence mute left dangling");Undo.PerformUndo();Need(asset.model.tracks.Any(t=>t.id==target.id)&&asset.model.patterns[0].tracks.Find(p=>p.trackId==other.id).automation.Last().unsupported==false,"Undo failed to restore references");});
                Check("shared chain picker adds effect modifier binding and Undo",()=>{window.track=0;window.mixerTab=1;window.BuildPane();int nodes=window.SelectedTrack.devices.nodes.Count;Click("chain-add-effect");Need(window.SelectedTrack.devices.nodes.Count==nodes,"Opening picker changed chain");PickEffect("Gain");Need(window.SelectedTrack.devices.nodes.Count==nodes+1,"Shared effect picker did not author data");Click("chain-add-modifier");PickEffect("LFO");Need(window.SelectedTrack.devices.modifiers.Count==1,"Modifier missing");LayoutChain(window);
                    var parameter=window.rootVisualElement.Q("chain-param-0-0");
                    var parameterRoot=parameter.panel.visualTree;var parameterAt=parameter.worldBound.center;
                    using(var right=PointerDownEvent.GetPooled(new Event{type=EventType.MouseDown,button=1,mousePosition=parameterAt})){right.target=parameter;parameter.SendEvent(right);}
                    PointerRelease(parameterRoot,parameterAt,1);
                    PickEffect("Modulate with/"+window.SelectedTrack.devices.modifiers[0].name);Need(window.SelectedTrack.devices.bindings.Count==1&&window.SelectedTrack.devices.bindings[0].schema==2,"Binding missing/current combine schema not used");Undo.PerformUndo();Need(window.SelectedTrack.devices.bindings.Count==0,"Undo failed to remove binding");Undo.PerformRedo();Need(window.SelectedTrack.devices.bindings.Count==1,"Redo failed to restore binding");});
                Check("automation creates precise points through named controls and Undo",()=>{window.pane=2;window.automationTarget=0;window.BuildPane();Click("add-automation-lane");Click("add-automation-point");var lane=window.Pattern.tracks.Find(p=>p.trackId==window.SelectedTrack.id).automation.Last();var field=window.rootVisualElement.Q<FloatField>("automation-point-line");Need(field!=null,"Precise point input missing");field.value=.375f;Need(lane.points[0].line==.375,"Fractional position rounded to an integer");Click("delete-automation-point");Need(lane.points.Count==0,"Point deletion failed");Undo.PerformUndo();Need(window.Pattern.tracks.Find(p=>p.trackId==window.SelectedTrack.id).automation.Last().points[0].line==.375,"Point Undo lost fractional time");});
                Check("beat interval appears only while beat events are on",()=>{window.pane=1;window.mixerTab=0;window.track=0;var selected=window.SelectedTrack;selected.beatTicks=false;window.BuildPane();Need(window.rootVisualElement.Q("mixer-beat-interval")==null,"Disabled beat interval still visible");window.SongEdit("track beat events",()=>selected.beatTicks=true,true);Need(window.rootVisualElement.Q("mixer-beat-interval")!=null,"Enabled beat interval missing");window.SongEdit("track beat events",()=>selected.beatTicks=false,true);});
                Check("mixer slider double-click resets through Undo and survives rebuild",()=>{window.pane=1;window.mixerTab=0;window.track=0;string id=window.SelectedTrack.id;window.SongEdit("fixture pre gain",()=>window.SelectedTrack.preVolume=.37f,true);DoubleClick(window.rootVisualElement.Q<ZuiMicroSlider>("mixer-pre-volume"));Need(Mathf.Approximately(asset.model.tracks.Find(t=>t.id==id).preVolume,new TrackData().preVolume),"Mixer double-click missed model default");Undo.PerformUndo();Need(Mathf.Approximately(asset.model.tracks.Find(t=>t.id==id).preVolume,.37f),"Mixer reset Undo failed");Undo.PerformRedo();Need(Mathf.Approximately(asset.model.tracks.Find(t=>t.id==id).preVolume,new TrackData().preVolume),"Mixer reset Redo failed");window.BuildPane();Need(window.rootVisualElement.Q<ZuiMicroSlider>("mixer-pre-volume")!=null,"Rebuilt mixer reset control missing");});
                Check("automation value and physical range double-click reset through Undo",()=>{window.track=0;var t=window.SelectedTrack;var pt=window.Pattern.tracks.Find(p=>p.trackId==t.id);var lane=new AutomationLane{id="reset-lane",target=new ParameterTarget{kind=ParameterKind.Mixer,trackId=t.id,parameter="postVolume"},points=new List<AutomationPoint>{new AutomationPoint{line=0,value=.8f}}};pt.automation.Add(lane);window.automationLane=pt.automation.Count-1;window.automationPoint=0;window.pane=2;window.BuildPane();DoubleClick(window.rootVisualElement.Q<ZuiMicroSlider>("automation-point-value"));Need(Mathf.Approximately(lane.points[0].value,new AutomationPoint().value),"Automation value did not reset");Undo.PerformUndo();Need(Mathf.Approximately(window.Pattern.tracks.Find(p=>p.trackId==t.id).automation.Last().points[0].value,.8f),"Automation reset Undo failed");Undo.PerformRedo();Need(Mathf.Approximately(window.Pattern.tracks.Find(p=>p.trackId==t.id).automation.Last().points[0].value,new AutomationPoint().value),"Automation reset Redo failed");window.pane=1;window.mixerTab=2;var node=new AudioEffectNodeData{type=ZoundEffectType.Gain,uid="reset-source-gain",p=new[]{1f}};t=asset.model.tracks.Find(x=>x.id==t.id);t.devices.nodes.Add(node);window.DeclareNativeSource(t,node);var source=t.sourceDevices.Find(s=>s.id==node.uid);Need(source!=null&&source.parameters.Count>0,"Source declaration has no parameter");var sp=source.parameters[0];var descriptor=ZoundEffectDescriptors.Get(node.type).parameters[sp.target.index];float span=descriptor.max-descriptor.min;sp.min=descriptor.min+span*.2f;sp.max=descriptor.max-span*.2f;window.BuildPane();var range=window.rootVisualElement.Query<ZuiMicroMinMax>().ToList().LastOrDefault(s=>s.tooltip.Contains("Declared physical source parameter range"));Need(range!=null&&Mathf.Approximately(range.low,sp.min)&&Mathf.Approximately(range.high,sp.max),"Fixture did not target its new source range");DoubleClick(range);Need(Mathf.Approximately(sp.min,descriptor.min)&&Mathf.Approximately(sp.max,descriptor.max),"Source range did not reset to descriptor bounds");Undo.PerformUndo();source=asset.model.tracks.Find(x=>x.id==t.id).sourceDevices.Find(s=>s.id==node.uid);Need(Mathf.Approximately(source.parameters[0].min,descriptor.min+span*.2f),"Source range reset Undo failed");Undo.PerformRedo();source=asset.model.tracks.Find(x=>x.id==t.id).sourceDevices.Find(s=>s.id==node.uid);Need(Mathf.Approximately(source.parameters[0].min,descriptor.min)&&Mathf.Approximately(source.parameters[0].max,descriptor.max),"Source range reset Redo failed");});
                Check("every mixer automation view is a read and preserves unsupported payload",()=>{window.pane=2;var pt=window.Pattern.tracks[0];pt.automation.Add(new AutomationLane{id="opaque",unsupported=true,diagnostic="preserve",rawSource="raw unsupported",target=new ParameterTarget{unresolved=true,parameter="foreign"}});string before=JsonUtility.ToJson(asset.model);for(int pane=1;pane<=2;pane++){window.pane=pane;for(int tab=0;tab<3;tab++){window.mixerTab=tab;window.BuildPane();}}Need(JsonUtility.ToJson(asset.model)==before,"UI build mutated authored data");});
            }
            finally{window.StopPreview();window.Close();DestroyImmediate(window);Undo.ClearUndo(asset);DestroyImmediate(asset);DestroyImmediate(inst);}
            report.AppendLine($"TOTAL passed={passed} failed={failed}");return report.ToString();
        }
    }
}
